"""Generate src/lexicon/wordlists.generated.ts from the AI pipeline wordlists.

Single source of truth stays in packages/ai-pipeline/src/wordlists/*.txt.
Run: python3 -I scripts/gen-lexicon.py
"""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
src = root.parent / "ai-pipeline" / "src" / "wordlists"
out = root / "src" / "lexicon" / "wordlists.generated.ts"

lists = {
    "language.profanity": "profanity.txt",
    "language.slur": "slurs.txt",
    "language.crude": "crude.txt",
    "language.sexual_reference": "sexual_reference.txt",
}

lines = [
    "/* GENERATED by scripts/gen-lexicon.py from ai-pipeline wordlists. Do not edit. */",
    "",
    "export const WORDLISTS: Record<string, string[]> = {",
]
for cat, fname in lists.items():
    words = sorted({w.strip().lower() for w in (src / fname).read_text().splitlines()
                    if w.strip() and not w.startswith("#")})
    body = ", ".join(f"'{w}'" for w in words)
    lines.append(f"  '{cat}': [{body}],")
lines.append("};")
strong = sorted({w.strip().lower() for w in (src / "profanity_strong.txt").read_text().splitlines()
                 if w.strip() and not w.startswith("#")})
lines.append("")
lines.append("/** Stems that make a profanity word severity 3 */")
lines.append("export const STRONG_STEMS: string[] = [" + ", ".join(f"'{w}'" for w in strong) + "];")
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out}")
